LINKEDIN_PERFIL_PAGE_HTML: str = "        <!doctype html>\n        <html lang=\"pt\">\n          <head>\n            <meta charset=\"UTF-8\" />\n            <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n            <title>Agente LinkedIn (perfil)</title>\n            <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n            <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n            <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n            <style>\n              :root {\n                --bg-0: #08090d;\n                --bg-1: #0f1117;\n                --bg-2: #151823;\n                --surface: #1a1d2a;\n                --surface-2: #20243a;\n                --line: rgba(255,255,255,0.08);\n                --line-strong: rgba(255,255,255,0.16);\n                --text: #f4f6fb;\n                --muted: #8a90a6;\n                --muted-soft: #b3b8c9;\n                --primary: #ff3d7f;\n                --primary-2: #ff6a00;\n                --accent: #38bdf8;\n                --accent-2: #818cf8;\n                --good: #34d399;\n                --bad: #f87171;\n                --warn: #fbbf24;\n                --shadow: 0 20px 60px rgba(0,0,0,0.45);\n              }\n              * { box-sizing: border-box; }\n              html, body { height: 100%; }\n              body {\n                margin: 0;\n                font-family: \"Inter\", \"Segoe UI\", system-ui, sans-serif;\n                background:\n                  radial-gradient(1200px 800px at 85% -10%, rgba(255,61,127,0.16), transparent 60%),\n                  radial-gradient(1000px 700px at -10% 110%, rgba(56,189,248,0.12), transparent 60%),\n                  var(--bg-0);\n                color: var(--text);\n                -webkit-font-smoothing: antialiased;\n                font-feature-settings: \"ss01\" on, \"cv11\" on;\n                padding: 28px 18px 64px;\n              }\n              .wrap { max-width: 1180px; margin: 0 auto; }\n              .nav {\n                display: flex; align-items: center; justify-content: space-between;\n                margin-bottom: 16px;\n              }\n              .nav a.back {\n                color: var(--muted-soft); text-decoration: none; font-weight: 500;\n                font-size: 0.92rem; display: inline-flex; gap: 6px; align-items: center;\n                padding: 6px 10px; border-radius: 8px; border: 1px solid var(--line);\n                background: rgba(255,255,255,0.02);\n              }\n              .nav a.back:hover { color: #fff; border-color: var(--line-strong); }\n              .brand {\n                display: flex; align-items: center; gap: 10px;\n                font-weight: 700; color: var(--muted-soft); font-size: 0.92rem;\n              }\n              .brand .logo-dot {\n                width: 10px; height: 10px; border-radius: 50%;\n                background: linear-gradient(135deg, var(--primary), var(--primary-2));\n                box-shadow: 0 0 12px rgba(255,61,127,0.6);\n              }\n\n              /* Hero */\n              .hero {\n                background: linear-gradient(180deg, var(--surface) 0%, var(--bg-1) 100%);\n                border: 1px solid var(--line);\n                border-radius: 20px;\n                padding: 22px 22px 18px;\n                box-shadow: var(--shadow);\n                position: relative;\n                overflow: hidden;\n              }\n              .hero::before {\n                content: \"\"; position: absolute; inset: -1px;\n                background: linear-gradient(135deg, rgba(255,61,127,0.25), transparent 35%, rgba(56,189,248,0.18) 70%, transparent 100%);\n                opacity: 0.6; pointer-events: none; border-radius: 20px;\n                mask: linear-gradient(#000, transparent 60%);\n                -webkit-mask: linear-gradient(#000, transparent 60%);\n              }\n              .hero-top { display: flex; align-items: center; gap: 14px; }\n              .hero-icon {\n                width: 44px; height: 44px; border-radius: 12px;\n                background: linear-gradient(135deg, var(--primary), var(--primary-2));\n                display: flex; align-items: center; justify-content: center;\n                color: #fff; font-weight: 800; box-shadow: 0 6px 24px rgba(255,61,127,0.4);\n                font-size: 1.05rem;\n              }\n              .title { margin: 0; font-size: 1.45rem; letter-spacing: -0.01em; }\n              .subtitle { margin: 4px 0 0; color: var(--muted); font-size: 0.92rem; }\n\n              .form { margin-top: 18px; display: grid; grid-template-columns: 1fr minmax(140px, 160px) auto auto auto; gap: 10px; }\n                            .hero-layout {\n                margin-top: 18px;\n                display: grid;\n                grid-template-columns: 1fr minmax(200px, 240px);\n                gap: 20px;\n                align-items: start;\n              }\n              .hero-main { min-width: 0; }\n              .hero-auth {\n                display: flex;\n                flex-direction: column;\n                gap: 10px;\n              }\n              .field-label {\n                margin: 0 0 8px;\n                font-size: 0.82rem;\n                font-weight: 600;\n                color: var(--muted-soft);\n                text-transform: uppercase;\n                letter-spacing: 0.06em;\n              }\n              .field-hint {\n                margin: 8px 0 0;\n                font-size: 0.8rem;\n                color: var(--muted);\n              }\n              .li-analyze-form {\n                display: grid;\n                grid-template-columns: 1fr;\n                gap: 10px;\n              }\n              .li-my-profile-form {\n                display: grid;\n                grid-template-columns: 1fr auto;\n                gap: 10px;\n              }\n              .analyze-actions {\n                display: flex;\n                flex-direction: column;\n                gap: 10px;\n              }\n              .analyze-actions .btn-analyze,\n              .analyze-actions .btn-auto-analyze {\n                width: 100%;\n              }\n              .auth-status-col {\n                display: flex;\n                flex-direction: column;\n                gap: 8px;\n                align-items: stretch;\n              }\n              .auth-status-col .badge {\n                justify-content: center;\n                padding: 10px 12px;\n                font-size: 0.85rem;\n              }\n              .btn-linkedin-block,\n              .btn-logout-block {\n                width: 100%;\n                text-align: center;\n              }\n              .btn-save-profile {\n                background: rgba(56,189,248,0.15);\n                border: 1px solid rgba(56,189,248,0.35);\n                color: var(--accent);\n                white-space: nowrap;\n              }\n              .btn-save-profile:disabled { opacity: 0.45; cursor: not-allowed; }\n              @media (max-width: 780px) {\n                .hero-layout { grid-template-columns: 1fr; }\n                .li-my-profile-form { grid-template-columns: 1fr; }\n              }\n              .li-only-form { grid-template-columns: 1fr auto; }\n              .li-auth-row { justify-content: flex-start; gap: 10px; }\n              .input-wrap {\n                position: relative;\n              }\n              .input-wrap::before {\n                content: \"@\"; position: absolute; left: 14px; top: 50%; transform: translateY(-50%);\n                color: var(--muted); font-weight: 600;\n              }\n              .input-wrap.no-at::before {\n                content: none;\n              }\n              .input-wrap.no-at input.profile {\n                padding-left: 14px;\n              }\n              input.profile {\n                width: 100%;\n                border-radius: 12px;\n                border: 1px solid var(--line);\n                background: rgba(8,9,13,0.6);\n                color: var(--text);\n                padding: 12px 14px 12px 30px;\n                font-family: inherit; font-size: 0.95rem;\n                outline: none; transition: border-color 0.15s, box-shadow 0.15s;\n              }\n              input.profile:focus { border-color: rgba(255,61,127,0.6); box-shadow: 0 0 0 4px rgba(255,61,127,0.12); }\n              button {\n                border: none; border-radius: 12px; padding: 11px 16px;\n                color: #fff; font-weight: 600; cursor: pointer; font-family: inherit;\n                font-size: 0.93rem; letter-spacing: 0.01em; transition: transform 0.05s, filter 0.15s;\n              }\n              button:hover { filter: brightness(1.06); }\n              button:active { transform: translateY(1px); }\n              .btn-login { background: rgba(255,255,255,0.06); border: 1px solid var(--line-strong); }\n              .btn-linkedin { background: #0a66c2; border: 1px solid rgba(255,255,255,0.22); color: #fff; }\n              .btn-linkedin:disabled { opacity: 0.45; cursor: not-allowed; }\n              .btn-auto-analyze {\n                background: linear-gradient(135deg, #0a66c2, #004182);\n                border: 1px solid rgba(255,255,255,0.2);\n                box-shadow: 0 6px 18px rgba(10,102,194,0.35);\n              }\n              .btn-auto-analyze:disabled { opacity: 0.45; cursor: not-allowed; filter: none; }\n              .btn-logout {\n                background: rgba(255,255,255,0.06);\n                border: 1px solid var(--line-strong);\n                color: var(--muted-soft);\n              }\n              .btn-logout:hover { color: #fff; border-color: rgba(248,113,113,0.45); }\n              .btn-analyze {\n                background: linear-gradient(135deg, var(--primary), var(--primary-2));\n                box-shadow: 0 8px 22px rgba(255,61,127,0.35);\n              }\n              .auth-row {\n                display: flex; align-items: center; justify-content: space-between;\n                flex-wrap: wrap; gap: 8px;\n                margin-top: 12px; color: var(--muted); font-size: 0.83rem;\n              }\n              .badge {\n                display: inline-flex; align-items: center; gap: 6px;\n                padding: 4px 10px; border-radius: 999px;\n                font-size: 0.78rem; font-weight: 600; border: 1px solid var(--line);\n                background: rgba(255,255,255,0.03); color: var(--muted-soft);\n              }\n              .badge.ok { color: var(--good); border-color: rgba(52,211,153,0.35); background: rgba(52,211,153,0.08); }\n              .badge.warn { color: var(--warn); border-color: rgba(251,191,36,0.35); background: rgba(251,191,36,0.08); }\n              .badge.bad { color: var(--bad); border-color: rgba(248,113,113,0.35); background: rgba(248,113,113,0.08); }\n              .badge.info { color: var(--accent); border-color: rgba(56,189,248,0.35); background: rgba(56,189,248,0.08); }\n              .badge .dot { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }\n\n              /* Results */\n              .results { margin-top: 18px; display: grid; gap: 16px; }\n              .empty {\n                border: 1px dashed var(--line-strong); border-radius: 16px;\n                padding: 28px; text-align: center; color: var(--muted);\n                background: rgba(255,255,255,0.02);\n              }\n              .empty .big { font-size: 1.05rem; color: var(--muted-soft); margin-bottom: 4px; }\n\n              .loading {\n                display: flex; align-items: center; gap: 12px;\n                background: var(--surface); border: 1px solid var(--line);\n                border-radius: 16px; padding: 18px 22px; color: var(--muted-soft);\n              }\n              .spinner {\n                width: 22px; height: 22px; border-radius: 50%;\n                border: 3px solid rgba(255,255,255,0.12);\n                border-top-color: var(--primary);\n                animation: spin 0.8s linear infinite;\n              }\n              @keyframes spin { to { transform: rotate(360deg); } }\n\n              /* Header da análise */\n              .analysis-header {\n                background: var(--surface); border: 1px solid var(--line);\n                border-radius: 16px; padding: 18px 20px; display: flex; gap: 16px;\n                align-items: center; justify-content: space-between; flex-wrap: wrap;\n              }\n              .analysis-header .who {\n                display: flex; align-items: center; gap: 14px;\n              }\n              .ig-avatar {\n                width: 56px; height: 56px; border-radius: 50%;\n                background: linear-gradient(135deg, #ffd76a, #ff3d7f 35%, #a855f7 70%, #38bdf8);\n                display: flex; align-items: center; justify-content: center;\n                color: #fff; font-weight: 800; font-size: 1.4rem;\n                box-shadow: 0 8px 22px rgba(168,85,247,0.25);\n              }\n              .analysis-header h2 { margin: 0; font-size: 1.18rem; letter-spacing: -0.01em; }\n              .analysis-header .who small { display: block; color: var(--muted); font-size: 0.82rem; margin-top: 2px; }\n              .analysis-header .header-badges { display: flex; gap: 8px; flex-wrap: wrap; }\n\n              /* KPI cards */\n              .kpi-grid {\n                display: grid; gap: 12px;\n                grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));\n              }\n              .kpi {\n                background: linear-gradient(180deg, var(--surface), var(--surface-2));\n                border: 1px solid var(--line);\n                border-radius: 14px;\n                padding: 14px 16px;\n                position: relative; overflow: hidden;\n              }\n              .kpi .label { font-size: 0.78rem; color: var(--muted); text-transform: uppercase; letter-spacing: 0.08em; font-weight: 600; }\n              .kpi .value { font-size: 1.6rem; font-weight: 800; margin-top: 4px; letter-spacing: -0.02em; }\n              .kpi .sub { font-size: 0.82rem; color: var(--muted-soft); margin-top: 2px; }\n              .kpi.accent { border-color: rgba(255,61,127,0.35); }\n              .kpi.accent::after {\n                content: \"\"; position: absolute; right: -20px; bottom: -20px;\n                width: 90px; height: 90px; border-radius: 50%;\n                background: radial-gradient(circle, rgba(255,61,127,0.25), transparent 70%);\n              }\n\n              /* Tabs */\n              .tabs {\n                display: flex; gap: 6px; padding: 6px;\n                background: var(--surface); border: 1px solid var(--line);\n                border-radius: 14px; overflow-x: auto;\n              }\n              .tab {\n                flex: 1; min-width: 100px; padding: 9px 12px;\n                border-radius: 10px; cursor: pointer; font-weight: 600;\n                color: var(--muted-soft); font-size: 0.88rem; text-align: center;\n                transition: background 0.15s, color 0.15s;\n                user-select: none; white-space: nowrap;\n              }\n              .tab:hover { color: #fff; }\n              .tab.active {\n                background: linear-gradient(135deg, var(--primary), var(--primary-2));\n                color: #fff;\n              }\n\n              .panel { display: none; }\n              .panel.active { display: grid; gap: 14px; }\n\n              .section {\n                background: var(--surface); border: 1px solid var(--line);\n                border-radius: 16px; padding: 18px 20px;\n              }\n              .section h3 {\n                margin: 0 0 12px; font-size: 1rem; letter-spacing: 0.01em;\n                display: flex; align-items: center; gap: 10px;\n              }\n              .section h3 .pill {\n                font-size: 0.7rem; font-weight: 600; padding: 3px 8px;\n                border-radius: 999px; background: rgba(255,61,127,0.12); color: var(--primary);\n                border: 1px solid rgba(255,61,127,0.25); letter-spacing: 0.04em; text-transform: uppercase;\n              }\n              .section h3 .pill.cool { background: rgba(56,189,248,0.12); color: var(--accent); border-color: rgba(56,189,248,0.25); }\n              .section h3 .pill.violet { background: rgba(129,140,248,0.12); color: var(--accent-2); border-color: rgba(129,140,248,0.25); }\n\n              /* Listas estilizadas */\n              .insight-list { list-style: none; padding: 0; margin: 0; display: grid; gap: 8px; }\n              .insight-list li {\n                background: rgba(255,255,255,0.02);\n                border: 1px solid var(--line);\n                border-left: 3px solid var(--accent);\n                border-radius: 10px;\n                padding: 10px 14px; font-size: 0.94rem; line-height: 1.5;\n              }\n              .insight-list.problems li { border-left-color: var(--bad); }\n              .insight-list.opps li { border-left-color: var(--good); }\n              .insight-list.actions li { border-left-color: var(--primary); counter-increment: actcount; }\n              .insight-list.actions { counter-reset: actcount; }\n              .insight-list.actions li::before {\n                content: counter(actcount); display: inline-flex;\n                width: 22px; height: 22px; border-radius: 50%;\n                background: rgba(255,61,127,0.18); color: var(--primary);\n                font-weight: 700; font-size: 0.78rem; align-items: center; justify-content: center;\n                margin-right: 8px; vertical-align: middle;\n              }\n              .insight-list.violet li { border-left-color: var(--accent-2); }\n\n              /* Format distribution bars */\n              .format-grid { display: grid; gap: 10px; }\n              .format-row {\n                display: grid; grid-template-columns: 110px 1fr 70px; gap: 10px;\n                align-items: center; font-size: 0.9rem;\n              }\n              .format-label { font-weight: 600; color: var(--muted-soft); text-transform: capitalize; }\n              .format-bar {\n                position: relative; height: 10px; border-radius: 999px;\n                background: rgba(255,255,255,0.06); overflow: hidden;\n              }\n              .format-fill {\n                position: absolute; inset: 0;\n                background: linear-gradient(90deg, var(--primary), var(--primary-2));\n                border-radius: 999px; transform-origin: left;\n              }\n              .format-pct { text-align: right; font-variant-numeric: tabular-nums; color: var(--muted-soft); }\n              .format-er { grid-column: 2 / 4; font-size: 0.78rem; color: var(--muted); margin-top: 2px; }\n\n              /* Top items */\n              .top-grid { display: grid; gap: 10px; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); }\n              .top-card {\n                border: 1px solid var(--line); border-radius: 12px;\n                background: rgba(255,255,255,0.02); padding: 12px 14px;\n                display: flex; gap: 12px; align-items: flex-start;\n              }\n              .top-card .rank {\n                width: 28px; height: 28px; border-radius: 8px;\n                background: rgba(255,61,127,0.15); color: var(--primary);\n                display: flex; align-items: center; justify-content: center;\n                font-weight: 800; flex-shrink: 0; font-size: 0.85rem;\n              }\n              .top-card .meta-row { display: flex; gap: 12px; flex-wrap: wrap; color: var(--muted-soft); font-size: 0.82rem; }\n              .top-card a { color: var(--accent); text-decoration: none; font-size: 0.82rem; }\n              .top-card a:hover { text-decoration: underline; }\n\n              /* Comparações temporais */\n              .compare-grid { display: grid; gap: 10px; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); }\n              .compare-card {\n                border: 1px solid var(--line); border-radius: 12px;\n                background: rgba(255,255,255,0.02); padding: 12px 14px;\n              }\n              .compare-card .label { font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); font-weight: 700; }\n              .compare-card .rows { margin-top: 8px; display: grid; gap: 4px; font-size: 0.88rem; }\n              .compare-card .delta { font-weight: 700; font-variant-numeric: tabular-nums; }\n              .delta.up { color: var(--good); }\n              .delta.down { color: var(--bad); }\n              .compare-card.empty-card { color: var(--muted); font-size: 0.88rem; text-align: center; padding: 18px; }\n\n              /* Hashtags */\n              .hashtag-grid { display: flex; flex-wrap: wrap; gap: 8px; }\n              .hashtag {\n                display: inline-flex; align-items: center; gap: 6px;\n                padding: 6px 10px; border-radius: 999px;\n                background: rgba(56,189,248,0.10); color: var(--accent);\n                border: 1px solid rgba(56,189,248,0.25);\n                font-size: 0.82rem; font-weight: 600;\n              }\n              .hashtag .count { color: var(--muted-soft); font-weight: 500; font-size: 0.75rem; }\n\n\n              /* LinkedIn metric cards (overview) */\n              .li-posts-cta-banner { border-color: rgba(129,140,248,0.35); background: rgba(129,140,248,0.06); }\n              .li-metrics-section { margin-top: 4px; }\n              .li-metrics-group { margin-top: 16px; }\n              .li-metrics-group:first-of-type { margin-top: 8px; }\n              .li-metrics-group-title {\n                font-size: 0.72rem; font-weight: 700; text-transform: uppercase;\n                letter-spacing: 0.1em; color: var(--muted); margin: 0 0 10px;\n              }\n              .li-metrics-grid {\n                display: grid;\n                grid-template-columns: repeat(auto-fill, minmax(188px, 1fr));\n                gap: 12px;\n              }\n              .li-metric-card {\n                background: linear-gradient(165deg, rgba(255,255,255,0.05), rgba(255,255,255,0.02));\n                border: 1px solid var(--line);\n                border-radius: 14px;\n                padding: 16px 18px;\n                min-height: 88px;\n                display: flex; flex-direction: column; justify-content: center;\n                transition: border-color 0.15s ease;\n              }\n              .li-metric-card:hover { border-color: var(--line-strong); }\n              .li-metric-card.is-muted { opacity: 0.72; }\n              .li-metric-card.is-unavailable .li-metric-value {\n                font-size: 0.72rem;\n                line-height: 1.35;\n                font-weight: 500;\n                color: var(--muted);\n              }\n              .li-metric-card.is-muted .li-metric-value { color: var(--muted); font-weight: 600; }\n              .li-metric-value {\n                font-size: 1.28rem; font-weight: 800; color: var(--text);\n                line-height: 1.2; letter-spacing: -0.02em;\n              }\n              .li-metric-label {\n                font-size: 0.8rem; color: var(--muted-soft, var(--muted));\n                margin-top: 8px; line-height: 1.35;\n              }\n              .li-metrics-empty {\n                color: var(--muted); font-size: 0.88rem; padding: 12px 0;\n              }\n              .section-desc {\n                color: var(--muted); font-size: 0.85rem; margin: -4px 0 0;\n                line-height: 1.45;\n              }\n\n              /* Metric pills */\n              .metric-pills { display: flex; flex-wrap: wrap; gap: 8px; }\n              .metric-pill {\n                background: rgba(255,255,255,0.04); border: 1px solid var(--line);\n                border-radius: 10px; padding: 8px 12px; font-size: 0.84rem;\n                color: var(--muted-soft);\n              }\n              .metric-pill strong { color: var(--text); margin-right: 4px; }\n\n              .gap-list { list-style: none; padding: 0; margin: 0; display: grid; gap: 6px; }\n              .gap-list li {\n                background: rgba(251,191,36,0.06); border: 1px solid rgba(251,191,36,0.25);\n                color: #fde68a; border-radius: 10px;\n                padding: 8px 12px; font-size: 0.86rem;\n              }\n\n              .err {\n                background: rgba(248,113,113,0.08); border: 1px solid rgba(248,113,113,0.3);\n                color: #fecaca; border-radius: 12px; padding: 12px 14px; font-size: 0.9rem;\n              }\n\n              \n              .li-posts-wrap { display: grid; gap: 12px; margin-top: 8px; }\n              .li-post-card {\n                border: 1px solid var(--line);\n                border-radius: 14px;\n                background: rgba(255,255,255,0.02);\n                padding: 14px 16px;\n                transition: border-color 0.15s;\n              }\n              .li-post-card.approved { border-color: rgba(52,211,153,0.45); background: rgba(52,211,153,0.06); }\n              .li-post-card.editing { border-color: rgba(56,189,248,0.45); }\n              .li-post-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; margin-bottom: 8px; }\n              .li-post-type {\n                font-size: 0.72rem; font-weight: 700; text-transform: uppercase;\n                letter-spacing: 0.06em; color: var(--accent-2);\n                background: rgba(129,140,248,0.12); padding: 3px 8px; border-radius: 999px;\n              }\n              .li-post-status { font-size: 0.78rem; color: var(--muted); }\n              .li-post-status.ok { color: var(--good); font-weight: 600; }\n              .li-post-title { font-weight: 700; margin: 0 0 6px; font-size: 0.95rem; }\n              .li-post-body {\n                white-space: pre-wrap; font-size: 0.9rem; line-height: 1.55;\n                color: var(--muted-soft); margin: 0 0 8px;\n              }\n              .li-post-meta { font-size: 0.78rem; color: var(--muted); margin-bottom: 10px; }\n              .li-post-actions { display: flex; flex-wrap: wrap; gap: 8px; }\n              .li-post-actions button {\n                padding: 7px 12px; font-size: 0.82rem; border-radius: 8px;\n              }\n              .btn-post-ok { background: rgba(52,211,153,0.15); border: 1px solid rgba(52,211,153,0.35); color: var(--good); }\n              .btn-post-edit { background: rgba(56,189,248,0.12); border: 1px solid rgba(56,189,248,0.3); color: var(--accent); }\n              .btn-post-redo { background: rgba(255,61,127,0.12); border: 1px solid rgba(255,61,127,0.3); color: var(--primary); }\n              .btn-post-del { background: transparent; border: 1px solid var(--line); color: var(--muted-soft); }\n              .li-post-edit-area {\n                width: 100%; min-height: 140px; margin: 8px 0 10px;\n                border-radius: 10px; border: 1px solid var(--line);\n                background: rgba(8,9,13,0.5); color: var(--text);\n                padding: 10px 12px; font-family: inherit; font-size: 0.9rem;\n                line-height: 1.5; resize: vertical;\n              }\n              .li-posts-loading { color: var(--muted); font-size: 0.88rem; padding: 12px 0; }\n              .li-post-image-wrap { margin: 10px 0 12px; }\n              .li-post-image {\n                max-width: 100%; max-height: 420px; width: auto; height: auto;\n                border-radius: 10px; border: 1px solid var(--line);\n                display: block; object-fit: contain;\n              }\n              .li-post-image-link {\n                display: inline-block; margin-top: 6px; font-size: 0.78rem;\n                color: var(--accent); text-decoration: none;\n              }\n              .li-post-image-link:hover { text-decoration: underline; }\n              .li-post-image-loading {\n                font-size: 0.85rem; color: var(--accent); margin: 8px 0 10px;\n              }\n              .li-post-image-section {\n                margin: 12px 0 4px; padding-top: 12px;\n                border-top: 1px dashed var(--line);\n              }\n              .li-post-image-head {\n                display: flex; justify-content: space-between; align-items: center;\n                margin-bottom: 8px; gap: 8px;\n              }\n              .li-post-image-label {\n                font-size: 0.72rem; font-weight: 700; text-transform: uppercase;\n                letter-spacing: 0.06em; color: var(--muted-soft);\n              }\n              .li-post-image-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }\n              .li-post-image-actions button {\n                padding: 7px 12px; font-size: 0.82rem; border-radius: 8px;\n              }\n              \n              .li-post-publish-section {\n                margin-top: 14px; padding-top: 12px;\n                border-top: 1px solid var(--line-strong);\n              }\n              .li-post-publish-label {\n                font-size: 0.72rem; font-weight: 700; text-transform: uppercase;\n                letter-spacing: 0.06em; color: var(--muted-soft); margin-bottom: 8px;\n              }\n              .li-post-publish-actions { display: flex; flex-wrap: wrap; gap: 8px; }\n              .li-post-publish-actions button {\n                padding: 8px 14px; font-size: 0.84rem; border-radius: 8px; font-weight: 600;\n              }\n              .btn-post-publish {\n                background: linear-gradient(135deg, #0a66c2, #004182);\n                border: 1px solid rgba(10,102,194,0.5); color: #fff;\n              }\n              .btn-post-publish:hover { filter: brightness(1.08); }\n              .btn-post-publish.secondary {\n                background: rgba(10,102,194,0.12); color: #7eb8f7;\n                border: 1px solid rgba(10,102,194,0.35);\n              }\n              .li-post-published-msg {\n                font-size: 0.85rem; color: var(--good); font-weight: 600;\n              }\n              .li-post-publish-loading { font-size: 0.85rem; color: var(--accent); }\n\n              .li-post-card.image-approved .li-post-image-section {\n                border-top-color: rgba(52,211,153,0.35);\n              }\n\n\n\n              @media (max-width: 680px) {\n                .form { grid-template-columns: 1fr; }\n                .analysis-header { flex-direction: column; align-items: flex-start; }\n              }\n            </style>\n          </head>\n          <body>\n            <div class=\"wrap\">\n              <div class=\"nav\">\n                <a class=\"back\" href=\"/\">← Voltar ao Diretor</a>\n                <div class=\"brand\"><span class=\"logo-dot\"></span> Agente LinkedIn (perfil)</div>\n              </div>\n              <div class=\"hero\">\n                <div class=\"hero-top\">\n                  <div class=\"hero-icon\">in</div>\n                  <div>\n                    <h1 class=\"title\">LinkedIn — perfil público e login OAuth</h1>\n                    <p class=\"subtitle\">Login com <strong>LinkedIn (OIDC)</strong> via Supabase. Na 1.ª vez cola o URL do teu perfil (fica na <strong>base de dados</strong>); depois o login + <strong>Auto-análise</strong> usam-no automaticamente. Para Instagram e outras redes, usa o <a href=\"/agentes/redes-sociais\" style=\"color:var(--accent)\">Agente Redes sociais</a>.</p>\n                  </div>\n                </div>\n                                <div class=\"hero-layout\">\n                  <div class=\"hero-main\">\n                    <p class=\"field-label\">Analisar outro perfil (URL público)</p>\n                    <div class=\"form li-analyze-form\">\n                      <div class=\"input-wrap no-at\">\n                        <input id=\"profileInput\" class=\"profile\" placeholder=\"https://www.linkedin.com/in/nome, /company/empresa ou /school/escola\" />\n                      </div>\n                      <div class=\"analyze-actions\">\n                        <button type=\"button\" class=\"btn-analyze\" onclick=\"runLinkedinProfileAnalysis()\">Analisar</button>\n                        <button type=\"button\" id=\"btnAutoAnalyze\" class=\"btn-auto-analyze\" onclick=\"runLinkedinAutoProfileAnalysis()\" disabled title=\"Guarda o teu perfil abaixo e inicia sessão\">Auto-análise</button>\n                      </div>\n                    </div>\n\n                    <p class=\"field-label\" style=\"margin-top:16px\">O meu perfil LinkedIn (guardado na base de dados)</p>\n                    <div class=\"form li-my-profile-form\">\n                      <div class=\"input-wrap no-at\">\n                        <input id=\"myProfileInput\" class=\"profile\" placeholder=\"https://www.linkedin.com/in/o-teu-nome\" />\n                      </div>\n                      <button type=\"button\" id=\"btnSaveMyProfile\" class=\"btn-save-profile\" onclick=\"saveMyLinkedinProfileToDatabase()\" disabled>Guardar na base de dados</button>\n                    </div>\n                    <p id=\"myProfileSaveHint\" class=\"field-hint\">Inicia sessão para associar o teu perfil à conta.</p>\n                  </div>\n\n                  <div class=\"hero-auth\">\n                    <button type=\"button\" id=\"btnLinkedinLogin\" class=\"btn-linkedin btn-linkedin-block\" onclick=\"startLinkedInSupabaseLogin()\">Login LinkedIn (Supabase)</button>\n                    <div class=\"auth-status-col\" id=\"authStatusCol\" style=\"display:none\">\n                      <span id=\"linkedinSupabaseStatus\" class=\"badge ok\"><span class=\"dot\"></span> Autenticado</span>\n                      <button type=\"button\" id=\"btnLinkedinLogout\" class=\"btn-logout btn-logout-block\" onclick=\"endLinkedInSupabaseSession()\">Terminar sessão</button>\n                    </div>\n                  </div>\n                </div>\n<div id=\"result\" class=\"results\">\n                <div class=\"empty\">\n                  <div class=\"big\">Sem análise ainda</div>\n                  <div>Faz <strong>Login</strong>, guarda o <strong>teu perfil</strong> na base de dados e usa <strong>Auto-análise</strong>; para outros perfis, cola o URL em cima e clica <strong>Analisar</strong> — o teu perfil é detectado automaticamente (Apify + OpenAI).</div>\n                </div>\n              </div>\n            </div>\n\n            <script>\n\n              let linkedinAnalysisSnapshot = null;\n              let linkedinGeneratedPosts = [];\n              let linkedinAnalysisIsOwnProfile = false;\n\n              const LINKEDIN_POST_TYPE_LABELS = {\n                texto: \"Post texto\", artigo: \"Artigo\", documento: \"Documento/PDF\",\n                poll: \"Sondagem\", video: \"Vídeo\", imagem: \"Imagem\", partilha: \"Partilha\"\n              };\n\n              function setLinkedinAnalysisSnapshot(data, isOwnProfile) {\n                linkedinAnalysisSnapshot = data ? JSON.parse(JSON.stringify(data)) : null;\n                if (typeof isOwnProfile === \"boolean\") {\n                  linkedinAnalysisIsOwnProfile = isOwnProfile;\n                } else if (data && typeof data.linkedin_own_profile === \"boolean\") {\n                  linkedinAnalysisIsOwnProfile = data.linkedin_own_profile;\n                }\n              }\n\n                            function enableGeneratePostsButton() {\n                const enabled = Boolean(linkedinAnalysisSnapshot) && linkedinAnalysisIsOwnProfile;\n                const label = linkedinGeneratedPosts.length ? \"Gerar novamente\" : \"Gerar posts\";\n                [\"btnGenerateLinkedinPosts\"].forEach((id) => {\n                  const btn = document.getElementById(id);\n                  if (!btn) return;\n                  btn.disabled = !enabled;\n                  btn.textContent = label;\n                });\n                document.querySelectorAll(\"[data-action=generate-linkedin-posts]\").forEach((btn) => {\n                  btn.disabled = !enabled;\n                  if (!btn.textContent || btn.textContent.includes(\"Gerar\")) btn.textContent = label;\n                });\n              }\n\n              function resetLinkedinPostsAfterAnalysis() {\n                linkedinGeneratedPosts = [];\n                const el = document.getElementById(\"linkedinPostsContainer\");\n                enableGeneratePostsButton();\n                if (el) {\n                  el.innerHTML = linkedinAnalysisSnapshot\n                    ? '<div class=\"li-posts-loading\">Análise concluída. Clica <strong>Gerar posts</strong> para criar publicações com IA.</div>'\n                    : '<div class=\"li-posts-loading\">Faz uma análise de perfil primeiro.</div>';\n                }\n              }\n\n              function linkedinPostTypeLabel(t) {\n                return LINKEDIN_POST_TYPE_LABELS[t] || t || \"Post\";\n              }\n\n              function renderLinkedinPostsContainer() {\n                const el = document.getElementById(\"linkedinPostsContainer\");\n                if (!el) return;\n                if (!linkedinGeneratedPosts.length) {\n                  el.innerHTML = '<div class=\"li-posts-loading\">Sem posts. Clica «Gerar posts».</div>';\n                  return;\n                }\n                el.innerHTML = linkedinGeneratedPosts.map((p) => {\n                  const st = p.status || \"draft\";\n                  const cls = [\"li-post-card\", st === \"approved\" ? \"approved\" : \"\", st === \"editing\" ? \"editing\" : \"\"].filter(Boolean).join(\" \");\n                  const statusLabel = st === \"approved\" ? '<span class=\"li-post-status ok\">Aprovado</span>' : (st === \"editing\" ? '<span class=\"li-post-status\">A editar</span>' : '<span class=\"li-post-status\">Rascunho</span>');\n                  const bodyBlock = st === \"editing\"\n                    ? `<textarea class=\"li-post-edit-area\" id=\"edit-area-${escapeHtml(p.id)}\">${escapeHtml(p.bodyEdit != null ? p.bodyEdit : p.body)}</textarea>`\n                    : `<p class=\"li-post-body\">${escapeHtml(p.body)}</p>`;\n                  const actions = st === \"editing\"\n                    ? `<button type=\"button\" class=\"btn-post-ok\" onclick=\"saveLinkedinPostEdit('${escapeHtml(p.id)}')\">Guardar</button>\n                       <button type=\"button\" class=\"btn-post-edit\" onclick=\"cancelLinkedinPostEdit('${escapeHtml(p.id)}')\">Cancelar</button>\n                       <button type=\"button\" class=\"btn-post-del\" onclick=\"deleteLinkedinPost('${escapeHtml(p.id)}')\">Apagar</button>`\n                    : `<button type=\"button\" class=\"btn-post-ok\" onclick=\"approveLinkedinPost('${escapeHtml(p.id)}')\" ${st === \"approved\" ? \"disabled\" : \"\"}>Aprovado</button>\n                       <button type=\"button\" class=\"btn-post-edit\" onclick=\"startLinkedinPostEdit('${escapeHtml(p.id)}')\">Editar</button>\n                       <button type=\"button\" class=\"btn-post-redo\" onclick=\"regenerateLinkedinPost('${escapeHtml(p.id)}')\">Refazer</button>`;\n                  const imgSt = p.image_status || \"draft\";\n                  let imageBlock = \"\";\n                  if (p.image_generating) {\n                    imageBlock = '<div class=\"li-post-image-loading\">A gerar imagem…</div>';\n                  } else if (p.generated_image_url) {\n                    const imgStatusLabel = imgSt === \"approved\"\n                      ? '<span class=\"li-post-status ok\">Imagem aprovada</span>'\n                      : '<span class=\"li-post-status\">Imagem em rascunho</span>';\n                    const imgActions = imgSt === \"approved\"\n                      ? `<button type=\"button\" class=\"btn-post-ok\" disabled>Aprovado</button>`\n                      : `<button type=\"button\" class=\"btn-post-ok\" onclick=\"approveLinkedinPostImage('${escapeHtml(p.id)}')\">Aprovado</button>\n                         <button type=\"button\" class=\"btn-post-redo\" onclick=\"regenerateLinkedinPostImage('${escapeHtml(p.id)}')\">Refazer</button>`;\n                    imageBlock = `\n                      <div class=\"li-post-image-section\">\n                        <div class=\"li-post-image-head\">\n                          <span class=\"li-post-image-label\">Imagem</span>\n                          ${imgStatusLabel}\n                        </div>\n                        <div class=\"li-post-image-wrap\">\n                          <img src=\"${escapeHtml(p.generated_image_url)}\" alt=\"Imagem do post\" class=\"li-post-image\" />\n                          <a class=\"li-post-image-link\" href=\"${escapeHtml(p.generated_image_url)}\" target=\"_blank\" rel=\"noopener noreferrer\">Abrir imagem</a>\n                        </div>\n                        <div class=\"li-post-image-actions\">${imgActions}</div>\n                      </div>`;\n                  }\n                                    let publishBlock = \"\";\n                  const publishAuthOk = hasLinkedinPublishAuthorization();\n                  const publishAuthBtn = publishAuthOk\n                    ? '<span class=\"li-post-status ok\" style=\"margin-left:8px\">Publicação autorizada</span>'\n                    : '<button type=\"button\" class=\"btn-post-publish secondary\" onclick=\"connectLinkedinPublish()\">Autorizar publicação no LinkedIn</button>';\n                  if (p.publishing_linkedin) {\n                    publishBlock = '<div class=\"li-post-publish-loading\">A publicar no LinkedIn…</div>';\n                  } else if (p.published_on_linkedin) {\n                    publishBlock = '<div class=\"li-post-publish-section\"><div class=\"li-post-published-msg\">Publicado no LinkedIn</div></div>';\n                  } else if (st === \"approved\") {\n                    const canPublishImage = p.image_status === \"approved\" && p.generated_image_url;\n                    const pubDisabled = publishAuthOk ? \"\" : \" disabled\";\n                    if (canPublishImage) {\n                      publishBlock = `\n                        <div class=\"li-post-publish-section\">\n                          <div class=\"li-post-publish-label\">Publicar no LinkedIn ${publishAuthBtn}</div>\n                          <p style=\"font-size:0.78rem;color:var(--muted);margin:0 0 8px\">O login Supabase analisa o perfil; autoriza aqui para publicar posts.</p>\n                          <div class=\"li-post-publish-actions\">\n                            <button type=\"button\" class=\"btn-post-publish\" onclick=\"publishLinkedinPost('${escapeHtml(p.id)}', true)\"${pubDisabled}>Publicar texto + imagem</button>\n                            <button type=\"button\" class=\"btn-post-publish secondary\" onclick=\"publishLinkedinPost('${escapeHtml(p.id)}', false)\"${pubDisabled}>Publicar só texto</button>\n                          </div>\n                        </div>`;\n                    } else {\n                      publishBlock = `\n                        <div class=\"li-post-publish-section\">\n                          <div class=\"li-post-publish-label\">Publicar no LinkedIn ${publishAuthBtn}</div>\n                          <p style=\"font-size:0.78rem;color:var(--muted);margin:0 0 8px\">O login Supabase analisa o perfil; autoriza aqui para publicar posts.</p>\n                          <div class=\"li-post-publish-actions\">\n                            <button type=\"button\" class=\"btn-post-publish\" onclick=\"publishLinkedinPost('${escapeHtml(p.id)}', false)\"${pubDisabled}>Publicar no LinkedIn</button>\n                          </div>\n                        </div>`;\n                    }\n                  }\n                  const cardCls = [cls, imgSt === \"approved\" && p.generated_image_url ? \"image-approved\" : \"\"].filter(Boolean).join(\" \");\n                  return `\n                    <div class=\"${cardCls}\" data-post-id=\"${escapeHtml(p.id)}\">\n                      <div class=\"li-post-head\">\n                        <span class=\"li-post-type\">${escapeHtml(linkedinPostTypeLabel(p.content_type))}</span>\n                        ${statusLabel}\n                      </div>\n                      <h4 class=\"li-post-title\">${escapeHtml(p.title || \"\")}</h4>\n                      ${bodyBlock}\n                      ${p.hook ? `<div class=\"li-post-meta\"><strong>Gancho:</strong> ${escapeHtml(p.hook)}</div>` : \"\"}\n                      ${p.cta ? `<div class=\"li-post-meta\"><strong>CTA:</strong> ${escapeHtml(p.cta)}</div>` : \"\"}\n                      ${imageBlock}\n                      ${p.angle ? `<div class=\"li-post-meta\"><strong>Ângulo:</strong> ${escapeHtml(p.angle)}</div>` : \"\"}\n                      ${publishBlock}\n                      <div class=\"li-post-actions\">${actions}</div>\n                    </div>\n                  `;\n                }).join(\"\").replace(/<div/g, \"<div\").replace(/<\\/div>/g, \"</div>\");\n              }\n\n              async function approveLinkedinPost(id) {\n                const p = linkedinGeneratedPosts.find((x) => x.id === id);\n                if (!p || p.status === \"approved\") return;\n                p.status = \"approved\";\n                renderLinkedinPostsContainer();\n                const wantImage = confirm(\n                  \"Queres gerar uma imagem para este post?\\n\\n\" +\n                  \"OK — gera uma imagem alinhada ao texto.\\n\" +\n                  \"Cancelar — mantém só o texto aprovado.\"\n                );\n                if (!wantImage) return;\n                await linkedinGeneratePostImage(p, null);\n              }\n\n              async function linkedinGeneratePostImage(p, editInstructions) {\n                if (!p) return;\n                p.image_generating = true;\n                p.image_status = \"draft\";\n                renderLinkedinPostsContainer();\n                try {\n                  const resp = await fetch(\"/agents/linkedin/generate-post-image\", {\n                    method: \"POST\",\n                    headers: { \"Content-Type\": \"application/json\" },\n                    body: JSON.stringify({\n                      post: {\n                        id: p.id,\n                        title: p.title,\n                        body: p.body,\n                        hook: p.hook,\n                        cta: p.cta,\n                        content_type: p.content_type,\n                      },\n                      edit_instructions: editInstructions || null,\n                    }),\n                  });\n                  const data = await resp.json().catch(() => ({}));\n                  if (!resp.ok) {\n                    const msg = data.detail || data.error || \"Falha ao gerar imagem.\";\n                    throw new Error(typeof msg === \"string\" ? msg : JSON.stringify(msg));\n                  }\n                  p.generated_image_url = data.image_url || \"\";\n                  p.generated_image_prompt = data.prompt_used || \"\";\n                  p.image_status = \"draft\";\n                } catch (err) {\n                  alert(err && err.message ? err.message : \"Não foi possível gerar a imagem.\");\n                } finally {\n                  p.image_generating = false;\n                  renderLinkedinPostsContainer();\n                }\n              }\n\n              function approveLinkedinPostImage(id) {\n                const p = linkedinGeneratedPosts.find((x) => x.id === id);\n                if (!p || !p.generated_image_url || p.image_status === \"approved\") return;\n                p.image_status = \"approved\";\n                renderLinkedinPostsContainer();\n              }\n\n              \n              \n              function getPersistedLinkedinPublishToken() {\n                try {\n                  const exp = Number(sessionStorage.getItem(LINKEDIN_PUBLISH_EXPIRES_KEY) || 0);\n                  if (exp && Date.now() > exp) {\n                    sessionStorage.removeItem(LINKEDIN_PUBLISH_TOKEN_KEY);\n                    sessionStorage.removeItem(LINKEDIN_PUBLISH_URN_KEY);\n                    sessionStorage.removeItem(LINKEDIN_PUBLISH_EXPIRES_KEY);\n                    return null;\n                  }\n                  return sessionStorage.getItem(LINKEDIN_PUBLISH_TOKEN_KEY) || null;\n                } catch (e) {\n                  return null;\n                }\n              }\n\n              function hasLinkedinPublishAuthorization() {\n                return Boolean(getPersistedLinkedinPublishToken());\n              }\n\n              function connectLinkedinPublish() {\n                window.location.href = \"/agents/linkedin/connect-publish\";\n              }\n\n              (function handlePublishOAuthReturn() {\n                try {\n                  const q = new URLSearchParams(window.location.search);\n                  if (q.get(\"publish_connected\") === \"1\") {\n                    history.replaceState({}, \"\", window.location.pathname);\n                  }\n                } catch (e) {}\n              })();\n\nasync function publishLinkedinPost(id, includeImage) {\n                const p = linkedinGeneratedPosts.find((x) => x.id === id);\n                if (!p || p.status !== \"approved\" || p.published_on_linkedin) return;\n                if (includeImage && (!p.generated_image_url || p.image_status !== \"approved\")) {\n                  alert(\"Aprova a imagem antes de publicar com imagem.\");\n                  return;\n                }\n                const modeLabel = includeImage ? \"texto + imagem\" : \"só texto\";\n                if (!confirm(\"Publicar no LinkedIn (\" + modeLabel + \")?\\n\\nSerá usada a conta com que fizeste login.\")) return;\n                const ctx = await getLinkedinSupabaseSession();\n                if (!ctx || !ctx.session) {\n                  alert(\"Inicia sessão com LinkedIn para publicar.\");\n                  return;\n                }\n                const publishTok = getPersistedLinkedinPublishToken();\n                if (!publishTok) {\n                  alert(\"Primeiro clica em «Autorizar publicação no LinkedIn» na secção Publicar.\");\n                  return;\n                }\n                const payload = appendLinkedinSessionFields({\n                  include_image: !!includeImage,\n                  linkedin_publish_access_token: publishTok,\n                  post: {\n                    id: p.id,\n                    title: p.title,\n                    body: p.body,\n                    hook: p.hook,\n                    cta: p.cta,\n                    content_type: p.content_type,\n                    generated_image_url: p.generated_image_url || null,\n                    status: p.status,\n                    image_status: p.image_status || null,\n                  },\n                }, ctx.session);\n                p.publishing_linkedin = true;\n                renderLinkedinPostsContainer();\n                try {\n                  const resp = await fetch(\"/agents/linkedin/publish-post\", {\n                    method: \"POST\",\n                    headers: { \"Content-Type\": \"application/json\" },\n                    body: JSON.stringify(payload),\n                  });\n                  const data = await resp.json().catch(() => ({}));\n                  if (!resp.ok) {\n                    const msg = data.detail || data.error || \"Falha ao publicar.\";\n                    throw new Error(typeof msg === \"string\" ? msg : JSON.stringify(msg));\n                  }\n                  p.published_on_linkedin = true;\n                  p.linkedin_post_urn = data.linkedin_post_urn || \"\";\n                  p.published_with_image = !!data.published_with_image;\n                } catch (err) {\n                  alert(err && err.message ? err.message : \"Não foi possível publicar no LinkedIn.\");\n                } finally {\n                  p.publishing_linkedin = false;\n                  renderLinkedinPostsContainer();\n                }\n              }\n\nasync function regenerateLinkedinPostImage(id) {\n                const p = linkedinGeneratedPosts.find((x) => x.id === id);\n                if (!p || !p.generated_image_url) return;\n                const instr = window.prompt(\"Instruções para refazer a imagem (opcional):\", \"\") || \"\";\n                await linkedinGeneratePostImage(p, instr || null);\n              }\n\n              function startLinkedinPostEdit(id) {\n                linkedinGeneratedPosts.forEach((x) => { if (x.status === \"editing\") x.status = \"draft\"; });\n                const p = linkedinGeneratedPosts.find((x) => x.id === id);\n                if (!p) return;\n                p.bodyEdit = p.body;\n                p.status = \"editing\";\n                renderLinkedinPostsContainer();\n              }\n\n              function cancelLinkedinPostEdit(id) {\n                const p = linkedinGeneratedPosts.find((x) => x.id === id);\n                if (!p) return;\n                p.status = p.status === \"approved\" ? \"approved\" : \"draft\";\n                delete p.bodyEdit;\n                renderLinkedinPostsContainer();\n              }\n\n              function saveLinkedinPostEdit(id) {\n                const p = linkedinGeneratedPosts.find((x) => x.id === id);\n                if (!p) return;\n                const ta = document.getElementById(\"edit-area-\" + id);\n                if (ta) p.body = ta.value.trim() || p.body;\n                delete p.bodyEdit;\n                p.status = \"draft\";\n                renderLinkedinPostsContainer();\n              }\n\n              function deleteLinkedinPost(id) {\n                if (!confirm(\"Apagar este post?\")) return;\n                linkedinGeneratedPosts = linkedinGeneratedPosts.filter((x) => x.id !== id);\n                renderLinkedinPostsContainer();\n              }\n\n              async function regenerateLinkedinPost(id) {\n                const p = linkedinGeneratedPosts.find((x) => x.id === id);\n                if (!p || !linkedinAnalysisSnapshot) return;\n                const instr = window.prompt(\"Instruções para refazer (opcional):\", \"\") || \"\";\n                const card = document.querySelector(`[data-post-id=\"${id}\"]`);\n                if (card) card.style.opacity = \"0.55\";\n                try {\n                  const res = await fetch(\"/agents/linkedin/regenerate-post\", {\n                    method: \"POST\",\n                    headers: { \"Content-Type\": \"application/json\" },\n                    body: JSON.stringify({\n                      analysis: linkedinAnalysisSnapshot,\n                      public_profile_data: linkedinAnalysisSnapshot.public_profile_data || {},\n                      profile_url: linkedinAnalysisSnapshot.profile_url || \"\",\n                      post: { id: p.id, content_type: p.content_type, title: p.title, body: p.body, hook: p.hook, cta: p.cta, angle: p.angle },\n                      edit_instructions: instr || null,\n                      language: \"pt-PT\",\n                    }),\n                  });\n                  const json = await res.json();\n                  if (!res.ok) throw new Error(json.detail || JSON.stringify(json));\n                  const updated = json.post || {};\n                  Object.assign(p, updated, { id: p.id, status: \"draft\" });\n                  delete p.bodyEdit;\n                  delete p.generated_image_url;\n                  delete p.generated_image_prompt;\n                  delete p.image_generating;\n                  delete p.image_status;\n                  delete p.published_on_linkedin;\n                  delete p.linkedin_post_urn;\n                  delete p.published_with_image;\n                  delete p.publishing_linkedin;\n                  renderLinkedinPostsContainer();\n                  const btnDone = document.getElementById(\"btnGenerateLinkedinPosts\");\n                  if (btnDone) { btnDone.disabled = false; btnDone.textContent = \"Gerar novamente\"; }\n                } catch (e) {\n                  alert(\"Erro ao refazer: \" + (e.message || e));\n                } finally {\n                  if (card) card.style.opacity = \"1\";\n                }\n              }\n\n              async function generateLinkedinPostsFromSnapshot() {\n                if (!linkedinAnalysisSnapshot) {\n                  alert(\"Faz primeiro uma análise de perfil.\");\n                  return;\n                }\n                if (!linkedinAnalysisIsOwnProfile) {\n                  alert(\"Gerar posts está disponível apenas na Auto-análise do teu perfil (login + perfil guardado).\");\n                  return;\n                }\n                const el = document.getElementById(\"linkedinPostsContainer\");\n                const btn = document.getElementById(\"btnGenerateLinkedinPosts\");\n                if (btn) { btn.disabled = true; btn.textContent = \"A gerar…\"; }\n                if (el) el.innerHTML = '<div class=\"li-posts-loading\">A gerar posts com IA…</div>';\n                try {\n                  const res = await fetch(\"/agents/linkedin/generate-posts\", {\n                    method: \"POST\",\n                    headers: { \"Content-Type\": \"application/json\" },\n                    body: JSON.stringify({\n                      analysis: linkedinAnalysisSnapshot,\n                      public_profile_data: linkedinAnalysisSnapshot.public_profile_data || {},\n                      profile_url: linkedinAnalysisSnapshot.profile_url || \"\",\n                      count: 3,\n                      language: \"pt-PT\",\n                    }),\n                  });\n                  const json = await res.json();\n                  if (!res.ok) throw new Error(json.detail || JSON.stringify(json));\n                  linkedinGeneratedPosts = (json.posts || []).map((row) => ({\n                    ...row,\n                    status: \"draft\",\n                  }));\n                  renderLinkedinPostsContainer();\n                  enableGeneratePostsButton();\n                } catch (e) {\n                  if (el) el.innerHTML = `<div class=\"err\">Erro: ${escapeHtml(e.message || String(e))}</div>`;\n                  const btnErr = document.getElementById(\"btnGenerateLinkedinPosts\");\n                  if (btnErr) { btnErr.disabled = false; btnErr.textContent = \"Gerar posts\"; }\n                }\n              }\n\n              const profileInput = document.getElementById(\"profileInput\");\n              const myProfileInput = document.getElementById(\"myProfileInput\");\n              const btnSaveMyProfile = document.getElementById(\"btnSaveMyProfile\");\n              const authStatusCol = document.getElementById(\"authStatusCol\");\n              const result = document.getElementById(\"result\");\n              const SUPABASE_PUBLIC_URL = ___SUPABASE_URL_JSON___;\n              const SUPABASE_ANON_KEY = ___SUPABASE_ANON_JSON___;\n\n              function updateLinkedinOAuthButton() {\n                const linkedinBtn = document.getElementById(\"btnLinkedinLogin\");\n                if (!linkedinBtn) return;\n                const supabaseOk = Boolean(SUPABASE_PUBLIC_URL && SUPABASE_ANON_KEY);\n                linkedinBtn.disabled = !supabaseOk;\n                linkedinBtn.style.opacity = supabaseOk ? \"1\" : \"0.55\";\n                linkedinBtn.title = supabaseOk\n                  ? \"OAuth LinkedIn (OIDC) via Supabase.\"\n                  : \"Define NEXT_PUBLIC_SUPABASE_URL e NEXT_PUBLIC_SUPABASE_ANON_KEY no .env e reinicia o servidor.\";\n              }\n              updateLinkedinOAuthButton();\n\n\n              \n              \n              \n              \n\n              const LINKEDIN_PROFILE_URL_KEY = \"plataforma_linkedin_profile_url\";\n              const LINKEDIN_PROVIDER_TOKEN_KEY = \"plataforma_linkedin_provider_token\";\n              const LINKEDIN_PUBLISH_TOKEN_KEY = \"plataforma_linkedin_publish_token\";\n              const LINKEDIN_PUBLISH_URN_KEY = \"plataforma_linkedin_publish_person_urn\";\n              const LINKEDIN_PUBLISH_EXPIRES_KEY = \"plataforma_linkedin_publish_expires_at\";\n              const LINKEDIN_ID_TOKEN_KEY = \"plataforma_linkedin_id_token\";\n\n              function getStoredLinkedinProfileUrl() {\n                try {\n                  return (localStorage.getItem(LINKEDIN_PROFILE_URL_KEY) || \"\").trim();\n                } catch (e) {\n                  return \"\";\n                }\n              }\n\n\n              function canonicalizeLinkedinProfileUrl(raw) {\n                const s = String(raw || \"\").trim();\n                if (!s) return \"\";\n                const noHash = s.split(\"#\")[0].trim();\n                let m = noHash.match(/linkedin\\.com\\/in\\/([a-zA-Z0-9\\-_%]+)/i);\n                if (m && m[1]) return \"https://www.linkedin.com/in/\" + decodeURIComponent(m[1]).replace(/\\/$/, \"\");\n                m = noHash.match(/linkedin\\.com\\/company\\/([a-zA-Z0-9\\-_%]+)/i);\n                if (m && m[1]) return \"https://www.linkedin.com/company/\" + decodeURIComponent(m[1]).replace(/\\/$/, \"\");\n                m = noHash.match(/linkedin\\.com\\/school\\/([a-zA-Z0-9\\-_%]+)/i);\n                if (m && m[1]) return \"https://www.linkedin.com/school/\" + decodeURIComponent(m[1]).replace(/\\/$/, \"\");\n                if (!/^https?:\\/\\//i.test(noHash) && !/linkedin\\.com/i.test(noHash)) {\n                  const slug = noHash.replace(/^\\/+/, \"\");\n                  if (slug) return \"https://www.linkedin.com/in/\" + slug;\n                }\n                if (/linkedin\\.com\\/(in|company|school)\\//i.test(noHash)) {\n                  const u = noHash.replace(/\\/$/, \"\");\n                  return /^https?:\\/\\//i.test(u) ? u : \"https://\" + u.replace(/^\\/+/, \"\");\n                }\n                return \"\";\n              }\n\n              function saveLinkedinProfileUrl(url) {\n                const u = canonicalizeLinkedinProfileUrl(url);\n                if (!u) return;\n                try {\n                  localStorage.setItem(LINKEDIN_PROFILE_URL_KEY, u);\n                } catch (e) { /* privado */ }\n              }\n\n              function applyStoredLinkedinProfileUrl() {\n                const stored = getStoredLinkedinProfileUrl();\n                if (!stored) return;\n                if (myProfileInput && !myProfileInput.value.trim()) {\n                  myProfileInput.value = stored;\n                }\n                if (profileInput) {\n                  profileInput.placeholder = \"https://www.linkedin.com/in/nome, /company/empresa ou /school/escola\";\n                }\n              }\n\n              function captureLinkedinOAuthTokens(session) {\n                if (!session) return;\n                try {\n                  if (session.provider_token) {\n                    sessionStorage.setItem(LINKEDIN_PROVIDER_TOKEN_KEY, session.provider_token);\n                  }\n                  const idTok = session.provider_id_token || (session.user && session.user.id_token);\n                  if (idTok) {\n                    sessionStorage.setItem(LINKEDIN_ID_TOKEN_KEY, idTok);\n                  }\n                } catch (e) { /* storage */ }\n              }\n\n              function getPersistedLinkedinProviderToken(session) {\n                if (session && session.provider_token) return session.provider_token;\n                try {\n                  return sessionStorage.getItem(LINKEDIN_PROVIDER_TOKEN_KEY) || null;\n                } catch (e) {\n                  return null;\n                }\n              }\n\n              function getPersistedLinkedinIdToken(session) {\n                try {\n                  if (session && session.provider_id_token) return session.provider_id_token;\n                  return sessionStorage.getItem(LINKEDIN_ID_TOKEN_KEY) || null;\n                } catch (e) {\n                  return null;\n                }\n              }\n\n              function appendLinkedinSessionFields(payload, session, options) {\n                options = options || {};\n                if (!payload || !session || !session.access_token) return payload;\n                payload.supabase_access_token = session.access_token;\n                const pt = getPersistedLinkedinProviderToken(session);\n                const idt = getPersistedLinkedinIdToken(session);\n                if (pt) payload.linkedin_provider_token = pt;\n                if (idt) payload.linkedin_id_token = idt;\n                if (options.includeStoredUrl !== false) {\n                  const stored = getStoredLinkedinProfileUrl();\n                  if (stored) payload.stored_linkedin_profile_url = stored;\n                }\n                return payload;\n              }\n\n\n              async function fetchLinkedinProfileFromDatabase(session) {\n                if (!session || !session.access_token) return null;\n                try {\n                  const res = await fetch(\"/agents/linkedin/stored-profile\", {\n                    method: \"POST\",\n                    headers: { \"Content-Type\": \"application/json\" },\n                    body: JSON.stringify({ supabase_access_token: session.access_token }),\n                  });\n                  if (res.status === 404) return null;\n                  const json = await res.json();\n                  if (res.ok && json.profile_url) return json.profile_url;\n                } catch (e) {\n                  console.warn(\"fetchLinkedinProfileFromDatabase:\", e);\n                }\n                return null;\n              }\n\n              async function saveLinkedinProfileToDatabase(session, profileUrl) {\n                if (!session || !session.access_token || !profileUrl) return false;\n                try {\n                  const res = await fetch(\"/agents/linkedin/stored-profile\", {\n                    method: \"POST\",\n                    headers: { \"Content-Type\": \"application/json\" },\n                    body: JSON.stringify({\n                      supabase_access_token: session.access_token,\n                      profile_url: profileUrl,\n                    }),\n                  });\n                  return res.ok;\n                } catch (e) {\n                  return false;\n                }\n              }\n\n              async function loadLinkedinProfileForSession(session) {\n                const dbUrl = await fetchLinkedinProfileFromDatabase(session);\n                if (dbUrl && myProfileInput) {\n                  myProfileInput.value = dbUrl;\n                  saveLinkedinProfileUrl(dbUrl);\n                  const hint = document.getElementById(\"myProfileSaveHint\");\n                  if (hint) hint.textContent = \"Perfil carregado da base de dados.\";\n                  return dbUrl;\n                }\n                if (myProfileInput) {\n                  const stored = getStoredLinkedinProfileUrl();\n                  if (stored && !myProfileInput.value.trim()) myProfileInput.value = stored;\n                }\n                return profileInput ? profileInput.value.trim() : \"\";\n              }\n\n              function escapeHtml(value) {\n                return String(value ?? \"\")\n                  .replace(/&/g, \"&amp;\")\n                  .replace(/</g, \"&lt;\")\n                  .replace(/>/g, \"&gt;\")\n                  .replace(/\"/g, \"&quot;\")\n                  .replace(/'/g, \"&#39;\");\n              }\n\n              function formatNumber(value) {\n                if (value === null || value === undefined || value === \"\") return \"—\";\n                const num = Number(value);\n                if (Number.isNaN(num)) return String(value);\n                if (Math.abs(num) >= 1e9) return (num / 1e9).toFixed(1).replace(/\\\\.0$/, \"\") + \"B\";\n                if (Math.abs(num) >= 1e6) return (num / 1e6).toFixed(1).replace(/\\\\.0$/, \"\") + \"M\";\n                if (Math.abs(num) >= 1e3) return (num / 1e3).toFixed(1).replace(/\\\\.0$/, \"\") + \"k\";\n                return Number.isInteger(num) ? String(num) : num.toFixed(2);\n              }\n\n              function formatPct(value) {\n                if (value === null || value === undefined) return \"—\";\n                const num = Number(value);\n                if (Number.isNaN(num)) return \"—\";\n                return num.toFixed(2) + \"%\";\n              }\n\n              function formatLinkedinAudienceCount(count) {\n                if (count === null || count === undefined || count === \"\") {\n                  return \"Dado não público no LinkedIn\";\n                }\n                const n = Number(count);\n                if (Number.isNaN(n)) return String(count);\n                return formatNumber(n);\n              }\n\n              function formatDelta(delta, pct) {\n                if (delta === null || delta === undefined) return { text: \"—\", cls: \"\" };\n                const num = Number(delta);\n                if (Number.isNaN(num)) return { text: \"—\", cls: \"\" };\n                const sign = num > 0 ? \"+\" : \"\";\n                const pctTxt = (pct !== null && pct !== undefined && !Number.isNaN(Number(pct)))\n                  ? ` (${sign}${Number(pct).toFixed(1)}%)`\n                  : \"\";\n                const cls = num > 0 ? \"up\" : (num < 0 ? \"down\" : \"\");\n                return { text: `${sign}${formatNumber(num)}${pctTxt}`, cls };\n              }\n\n              function arrow(cls) {\n                if (cls === \"up\") return \"▲\";\n                if (cls === \"down\") return \"▼\";\n                return \"—\";\n              }\n\n              function listSection(items, klass = \"\") {\n                if (!Array.isArray(items) || !items.length) {\n                  return `<li style=\"color: var(--muted)\">Sem dados suficientes.</li>`;\n                }\n                return items.map(item => `<li>${escapeHtml(item)}</li>`).join(\"\");\n              }\n\n              function renderHeader(data) {\n                const username = data.profile_username || \"n/d\";\n                const confidence = (data.confianca_analise || \"baixa\").toLowerCase();\n                const confCls = confidence === \"alta\" ? \"ok\" : (confidence === \"media\" ? \"warn\" : \"bad\");\n                const profile = data.public_profile_data || {};\n                const quality = (profile.data_quality || \"—\").toString();\n                const qCls = quality === \"alta\" ? \"ok\" : (quality === \"media\" ? \"warn\" : \"bad\");\n                const initial = escapeHtml(username.charAt(0).toUpperCase() || \"?\");\n                const headline = profile.headline ? String(profile.headline) : \"\";\n                const employer = profile.employer ? String(profile.employer) : \"\";\n                const subParts = [];\n                if (headline) subParts.push(headline);\n                if (employer) subParts.push(employer);\n                const subLine = subParts.length ? subParts.join(\" · \") : \"perfil LinkedIn\";\n                const profileUrl = profile.profile_url || data.profile_url || \"\";\n                const method = profile.collection_method || data.source || \"\";\n                const methodBadge = method && String(method).toLowerCase().includes(\"apify\")\n                  ? `<span class=\"badge info\"><span class=\"dot\"></span> Dados: Apify (posts públicos)</span>`\n                  : (method ? `<span class=\"badge\"><span class=\"dot\"></span> ${escapeHtml(String(method))}</span>` : \"\");\n\n                return `\n                  <div class=\"analysis-header\">\n                    <div class=\"who\">\n                      <div class=\"ig-avatar\">${initial}</div>\n                      <div>\n                        <h2>@${escapeHtml(username)}</h2>\n                        <small>${escapeHtml(subLine)}</small>\n                        ${profileUrl ? `<small><a href=\"${escapeHtml(profileUrl)}\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--accent)\">Ver perfil no LinkedIn ↗</a></small>` : \"\"}\n                      </div>\n                    </div>\n                    <div class=\"header-badges\">\n                      <span class=\"badge ${confCls}\"><span class=\"dot\"></span> Confiança: ${escapeHtml(confidence)}</span>\n                      <span class=\"badge ${qCls}\"><span class=\"dot\"></span> Qualidade dados: ${escapeHtml(quality)}</span>\n                      ${methodBadge}\n                    </div>\n                  </div>\n                `;\n              }\n\n              function renderKpis(data) {\n                const profile = data.public_profile_data || {};\n                const enrichment = profile.apify_enrichment || {};\n                const cadence = enrichment.posting_cadence || {};\n                const avgReact = enrichment.avg_reactions_per_post;\n                const avgComm = enrichment.avg_comments_per_post;\n                const engPct = enrichment.avg_engagement_pct ?? profile.engagement_rate;\n                const kpis = [\n                  { label: (String(data.profile_url || profile.profile_url || \"\").toLowerCase().includes(\"/company/\") || String(data.profile_url || profile.profile_url || \"\").toLowerCase().includes(\"/school/\")) ? \"Seguidores\" : \"Ligações\", value: formatLinkedinAudienceCount(profile.followers_count), sub: profile.employer ? String(profile.employer).slice(0, 40) : \"\", accent: true },\n                  { label: \"Publicações\", value: formatNumber(profile.posts_count || enrichment.posts_analyzed || (profile.recent_posts || []).length), sub: cadence.posts_last_30_days !== undefined ? `${cadence.posts_last_30_days} nos últimos 30d` : \"\" },\n                  { label: \"Reações médias\", value: avgReact !== undefined ? formatNumber(avgReact) : \"—\", sub: \"por publicação\" },\n                  { label: \"Comentários médios\", value: avgComm !== undefined ? formatNumber(avgComm) : \"—\", sub: engPct !== null && engPct !== undefined ? `eng. ${formatPct(engPct)}` : \"por publicação\" },\n                ];\n\n                return `\n                  <div class=\"kpi-grid\">\n                    ${kpis.map(k => `\n                      <div class=\"kpi ${k.accent ? \"accent\" : \"\"}\">\n                        <div class=\"label\">${k.label}</div>\n                        <div class=\"value\">${k.value}</div>\n                        ${k.sub ? `<div class=\"sub\">${escapeHtml(k.sub)}</div>` : \"\"}\n                      </div>\n                    `).join(\"\")}\n                  </div>\n                `;\n              }\n\n              const LINKEDIN_FMT_LABELS = { texto: \"Post texto\", artigo: \"Artigo\", documento: \"Documento/PDF\", poll: \"Sondagem\", imagem: \"Imagem\", video: \"Vídeo\", evento: \"Evento\", partilha: \"Partilha\", desconhecido: \"Outro\" };\n              function linkedinFormatLabel(key) { return LINKEDIN_FMT_LABELS[key] || key; }\n\n              function renderFormatBars(distribution) {\n                if (!distribution || typeof distribution !== \"object\") {\n                  return `<div style=\"color: var(--muted)\">Sem dados de formato.</div>`;\n                }\n                const entries = Object.entries(distribution);\n                if (!entries.length) return `<div style=\"color: var(--muted)\">Sem dados de formato.</div>`;\n                entries.sort((a, b) => (b[1].share_pct || 0) - (a[1].share_pct || 0));\n                return `\n                  <div class=\"format-grid\">\n                    ${entries.map(([fmt, info]) => {\n                      const share = typeof info.share_pct === \"number\" ? info.share_pct : 0;\n                      const er = info.avg_engagement_pct;\n                      return `\n                        <div class=\"format-row\">\n                          <div class=\"format-label\">${escapeHtml(linkedinFormatLabel(fmt))}</div>\n                          <div>\n                            <div class=\"format-bar\"><div class=\"format-fill\" style=\"width:${Math.max(2, share)}%\"></div></div>\n                            ${er !== null && er !== undefined ? `<div class=\"format-er\">interações médias ${Number(er).toFixed(1)}</div>` : \"\"}\n                          </div>\n                          <div class=\"format-pct\">${share.toFixed(1)}%</div>\n                        </div>\n                      `;\n                    }).join(\"\")}\n                  </div>\n                `;\n              }\n\n              function renderTopCards(items, type) {\n                if (!Array.isArray(items) || !items.length) {\n                  return `<div style=\"color: var(--muted)\">Sem ${type}.</div>`;\n                }\n                return `\n                  <div class=\"top-grid\">\n                    ${items.map((item, idx) => `\n                      <div class=\"top-card\">\n                        <div class=\"rank\">#${idx + 1}</div>\n                        <div style=\"flex:1; min-width:0\">\n                          <div class=\"meta-row\">\n                            <span>reações ${formatNumber(item.likes ?? item.reactions_total)}</span>\n                            <span>com. ${formatNumber(item.comments ?? item.commentsCount)}</span>\n                            ${item.type ? `<span>${escapeHtml(linkedinFormatLabel(item.type))}</span>` : \"\"}\n                          </div>\n                          ${item.url ? `<a href=\"${escapeHtml(item.url)}\" target=\"_blank\" rel=\"noopener\">abrir no LinkedIn ↗</a>` : \"\"}\n                        </div>\n                      </div>\n                    `).join(\"\")}\n                  </div>\n                `;\n              }\n\n              function renderComparisons(comparisons) {\n                const blocks = [\n                  { key: \"one_week\", label: \"1 semana\" },\n                  { key: \"two_weeks\", label: \"2 semanas\" },\n                  { key: \"one_month\", label: \"1 mês\" },\n                ];\n                return `\n                  <div class=\"compare-grid\">\n                    ${blocks.map(b => {\n                      const obj = (comparisons || {})[b.key];\n                      if (!obj || !obj.available) {\n                        return `<div class=\"compare-card empty-card\"><div class=\"label\">${b.label}</div><div style=\"margin-top:6px\">sem histórico ainda</div></div>`;\n                      }\n                      const f = obj.followers || {};\n                      const e = obj.engagement_rate || {};\n                      const p = obj.posts || {};\n                      const df = formatDelta(f.delta, f.delta_pct);\n                      const de = formatDelta(e.delta, e.delta_pct);\n                      const dp = formatDelta(p.delta, p.delta_pct);\n                      return `\n                        <div class=\"compare-card\">\n                          <div class=\"label\">${b.label}</div>\n                          <div class=\"rows\">\n                            <div>Ligações <span class=\"delta ${df.cls}\">${arrow(df.cls)} ${df.text}</span></div>\n                            <div>Engagement <span class=\"delta ${de.cls}\">${arrow(de.cls)} ${de.text}</span></div>\n                            <div>Publicações <span class=\"delta ${dp.cls}\">${arrow(dp.cls)} ${dp.text}</span></div>\n                          </div>\n                        </div>\n                      `;\n                    }).join(\"\")}\n                  </div>\n                `;\n              }\n\n\n                            const METRIC_UNAVAILABLE_PUBLIC = \"Dado não público no LinkedIn\";\n\n              const LINKEDIN_METRIC_LABELS = {\n                taxa_engagement_publicacoes: \"Taxa de engagement\",\n                publicacoes_no_periodo: \"Publicações no período\",\n                cadencia_dias_entre_posts: \"Intervalo entre posts\",\n                ligacoes: \"Ligações\",\n                seguidores: \"Seguidores\",\n                publicacoes_analisadas: \"Publicações analisadas\",\n                reacoes_medias_por_publicacao: \"Reações médias\",\n                comentarios_medios_por_publicacao: \"Comentários médios\",\n                cadencia_publicacao: \"Cadência de publicação\",\n                tipo_conteudo_mais_eficaz: \"Formato mais eficaz\",\n                alcance_medio: \"Alcance médio\",\n                impressoes: \"Impressões\",\n                visualizacoes_perfil: \"Visualizações do perfil\",\n              };\n\n              function getLinkedinPageKind(ctx) {\n                const data = ctx || linkedinAnalysisSnapshot || {};\n                const kind = data.linkedin_page_kind;\n                if (kind === \"organization\" || kind === \"personal\") return kind;\n                const url = String(data.profile_url || \"\").toLowerCase();\n                if (url.includes(\"/company/\") || url.includes(\"/school/\")) return \"organization\";\n                return \"personal\";\n              }\n\n              function humanizeMetricKey(key, pageKind) {\n                const k = String(key || \"\").trim();\n                if (!k) return \"\";\n                if (k === \"ligacoes\" && pageKind === \"organization\") return \"Seguidores\";\n                if (LINKEDIN_METRIC_LABELS[k]) return LINKEDIN_METRIC_LABELS[k];\n                return k.replace(/_/g, \" \").replace(/\\b\\w/g, (c) => c.toUpperCase());\n              }\n\n              function isMetricValueMissing(value) {\n                const raw = String(value == null ? \"\" : value).trim();\n                if (!raw) return true;\n                const low = raw.toLowerCase();\n                return (\n                  low === \"sem dados públicos disponíveis.\" ||\n                  low === \"sem dados públicos disponíveis\" ||\n                  low === \"dado não público no linkedin\" ||\n                  low === \"n/d\" || low === \"—\" || low.includes(\"sem dados públicos\") ||\n                  low.includes(\"dado não público\")\n                );\n              }\n\n              function renderLinkedinMetricCards(obj, ctx) {\n                const pageKind = getLinkedinPageKind(ctx);\n                if (!obj || typeof obj !== \"object\" || Array.isArray(obj)) {\n                  return '<div class=\"li-metrics-empty\">Sem indicadores para este perfil.</div>';\n                }\n                const entries = Object.entries(obj).filter(([k]) => String(k).trim());\n                if (!entries.length) {\n                  return '<div class=\"li-metrics-empty\">Sem indicadores para este perfil.</div>';\n                }\n                return `\n                  <div class=\"li-metrics-grid\">\n                    ${entries.map(([k, v]) => {\n                      const missing = isMetricValueMissing(v);\n                      const display = missing ? METRIC_UNAVAILABLE_PUBLIC : String(v).trim();\n                      const cls = missing ? \"li-metric-card is-muted is-unavailable\" : \"li-metric-card\";\n                      const title = missing ? \"O LinkedIn não expõe este dado publicamente ou o scraper não o devolveu.\" : \"\";\n                      return `\n                        <div class=\"${cls}\" title=\"${escapeHtml(title)}\">\n                          <div class=\"li-metric-value\">${escapeHtml(display)}</div>\n                          <div class=\"li-metric-label\">${escapeHtml(humanizeMetricKey(k, pageKind))}</div>\n                        </div>\n                      `;\n                    }).join(\"\")}\n                  </div>\n                `.replace(/<\\/motion>/g, \"</div>\").replace(/<div/g, \"<div\").replace(/<div class=\"li-metric-value\">/g, '<div class=\"li-metric-value\">');\n              }\n\n              function renderCadence(cadence) {\n                cadence = cadence || {};\n                const pills = [];\n                if (cadence.posts_last_30_days !== undefined) pills.push([\"Posts (30d)\", cadence.posts_last_30_days]);\n                if (cadence.avg_days_between_posts !== undefined) pills.push([\"Intervalo médio\", `${cadence.avg_days_between_posts} dias`]);\n                if (cadence.last_post_at) {\n                  const d = new Date(cadence.last_post_at);\n                  pills.push([\"Último post\", isNaN(d.getTime()) ? cadence.last_post_at : d.toLocaleDateString(\"pt-PT\")]);\n                }\n                if (!pills.length) return `<div class=\"metric-pills\"><span class=\"metric-pill\">Sem datas nas publicações recolhidas.</span></div>`;\n                return `\n                  <div class=\"metric-pills\">\n                    ${pills.map(([k, v]) => `<span class=\"metric-pill\"><strong>${escapeHtml(k)}:</strong> ${escapeHtml(v)}</span>`).join(\"\")}\n                  </div>\n                `;\n              }\n\n                            function renderTabs(showPostsTab) {\n                const postsTab = showPostsTab\n                  ? '<div class=\"tab\" data-target=\"posts\">Posts</div>'\n                  : \"\";\n                return `\n                  <div class=\"tabs\">\n                    <div class=\"tab active\" data-target=\"overview\">Visão Geral</div>\n                    ${postsTab}\n                    <div class=\"tab\" data-target=\"content\">Tipos de conteúdo</div>\n                    <div class=\"tab\" data-target=\"evolution\">Plano &amp; Ações</div>\n                  </div>\n                `;\n              }\n\nfunction attachTabHandlers() {\n                document.querySelectorAll(\".tab\").forEach(tab => {\n                  tab.addEventListener(\"click\", () => {\n                    document.querySelectorAll(\".tab\").forEach(t => t.classList.remove(\"active\"));\n                    document.querySelectorAll(\".panel\").forEach(p => p.classList.remove(\"active\"));\n                    tab.classList.add(\"active\");\n                    const target = tab.getAttribute(\"data-target\");\n                    const panel = document.getElementById(\"panel-\" + target);\n                    if (panel) panel.classList.add(\"active\");\n                  });\n                });\n              }\n\n              let linkedinSupabaseClient = null;\n\n              async function getLinkedinSupabaseClient() {\n                if (!SUPABASE_PUBLIC_URL || !SUPABASE_ANON_KEY) return null;\n                if (linkedinSupabaseClient) return linkedinSupabaseClient;\n                const { createClient } = await import(\"https://esm.sh/@supabase/supabase-js@2\");\n                linkedinSupabaseClient = createClient(SUPABASE_PUBLIC_URL, SUPABASE_ANON_KEY, {\n                  auth: { detectSessionInUrl: true, persistSession: true, autoRefreshToken: true },\n                });\n                return linkedinSupabaseClient;\n              }\n\n              async function initSupabaseAuthFromUrl() {\n                const sb = await getLinkedinSupabaseClient();\n                if (!sb) return null;\n                const search = window.location.search || \"\";\n                const hash = window.location.hash || \"\";\n                const params = new URLSearchParams(search);\n                const code = params.get(\"code\");\n                try {\n                  if (code) await sb.auth.exchangeCodeForSession(code);\n                  else if (hash && (hash.includes(\"access_token\") || hash.includes(\"refresh_token\"))) {\n                    await sb.auth.getSession();\n                  }\n                } catch (e) {\n                  console.warn(\"initSupabaseAuthFromUrl:\", e);\n                }\n                if (code || (hash && hash.includes(\"access_token\"))) {\n                  window.history.replaceState({}, \"\", window.location.pathname);\n                }\n                return sb;\n              }\n\n              async function getLinkedinSupabaseSession() {\n                const sb = await getLinkedinSupabaseClient();\n                if (!sb) return null;\n                const { data, error } = await sb.auth.getSession();\n                if (error || !data.session) return null;\n                return { sb, session: data.session };\n              }\n\n              function updateLinkedinAuthButtons(connected) {\n                const loginBtn = document.getElementById(\"btnLinkedinLogin\");\n                const col = document.getElementById(\"authStatusCol\");\n                const autoBtn = document.getElementById(\"btnAutoAnalyze\");\n                const saveBtn = document.getElementById(\"btnSaveMyProfile\");\n                if (loginBtn) loginBtn.style.display = connected ? \"none\" : \"\";\n                if (col) col.style.display = connected ? \"flex\" : \"none\";\n                if (autoBtn) autoBtn.disabled = !connected;\n                if (saveBtn) saveBtn.disabled = !connected;\n              }\n\n              function updateAutoAnalyzeButton() {\n                const autoBtn = document.getElementById(\"btnAutoAnalyze\");\n                if (!autoBtn) return;\n                const hasMy = myProfileInput && myProfileInput.value.trim();\n                autoBtn.title = hasMy\n                  ? \"Analisa o teu perfil guardado (sessão + Apify)\"\n                  : \"Guarda o teu perfil abaixo e inicia sessão\";\n              }\n\n              async function startLinkedInSupabaseLogin() {\n                if (!SUPABASE_PUBLIC_URL || !SUPABASE_ANON_KEY) {\n                  alert(\"Supabase não configurado no servidor (.env).\");\n                  return;\n                }\n                try {\n                  const sb = await getLinkedinSupabaseClient();\n                  if (!sb) return;\n                  const redirectTo = window.location.origin + window.location.pathname;\n                  const { error } = await sb.auth.signInWithOAuth({\n                    provider: \"linkedin_oidc\",\n                    options: {\n                      redirectTo,\n                      scopes: \"openid profile email w_member_social\",\n                    },\n                  });\n                  if (error) throw error;\n                } catch (e) {\n                  alert(\"Erro no login: \" + (e.message || e));\n                }\n              }\n\n              async function endLinkedInSupabaseSession() {\n                try {\n                  const sb = await getLinkedinSupabaseClient();\n                  if (sb) await sb.auth.signOut();\n                  sessionStorage.removeItem(LINKEDIN_PROVIDER_TOKEN_KEY);\n                  sessionStorage.removeItem(LINKEDIN_ID_TOKEN_KEY);\n                } catch (e) { /* */ }\n                updateLinkedinAuthButtons(false);\n                updateAutoAnalyzeButton();\n              }\n\n              async function refreshLinkedinSupabaseSession() {\n                const ctx = await getLinkedinSupabaseSession();\n                updateLinkedinAuthButtons(Boolean(ctx));\n                if (ctx) {\n                  captureLinkedinOAuthTokens(ctx.session);\n                  await loadLinkedinProfileForSession(ctx.session);\n                  await tryResolveLinkedinProfileUrl(ctx.sb);\n                }\n                updateAutoAnalyzeButton();\n              }\n\n              async function tryResolveLinkedinProfileUrl(sb) {\n                if (!sb) return;\n                try {\n                  const res = await fetch(\"/agents/linkedin/resolve-profile-url\", {\n                    method: \"POST\",\n                    headers: { \"Content-Type\": \"application/json\" },\n                    body: JSON.stringify(\n                      appendLinkedinSessionFields(\n                        { messages: [], language: \"pt-PT\", platform: \"linkedin\" },\n                        (await getLinkedinSupabaseSession())?.session,\n                        { includeStoredUrl: true }\n                      )\n                    ),\n                  });\n                  const json = await res.json();\n                  if (res.ok && json.profile_url && myProfileInput && !myProfileInput.value.trim()) {\n                    myProfileInput.value = json.profile_url;\n                    saveLinkedinProfileUrl(json.profile_url);\n                  }\n                } catch (e) {\n                  console.warn(\"tryResolveLinkedinProfileUrl:\", e);\n                }\n              }\n\n              async function saveMyLinkedinProfileToDatabase() {\n                const ctx = await getLinkedinSupabaseSession();\n                if (!ctx) {\n                  alert(\"Inicia sessão primeiro.\");\n                  return;\n                }\n                const url = canonicalizeLinkedinProfileUrl(myProfileInput ? myProfileInput.value.trim() : \"\");\n                if (!url) {\n                  alert(\"URL inválido.\");\n                  return;\n                }\n                const ok = await saveLinkedinProfileToDatabase(ctx.session, url);\n                const hint = document.getElementById(\"myProfileSaveHint\");\n                if (hint) hint.textContent = ok ? \"Perfil guardado na base de dados.\" : \"Erro ao guardar. Confirma a migration no Supabase.\";\n                if (ok) {\n                  saveLinkedinProfileUrl(url);\n                  updateAutoAnalyzeButton();\n                }\n              }\n\n              async function runLinkedinProfileAnalysis(options) {\n                options = options || {};\n                const autoAuthenticated = options.autoAuthenticated === true;\n                const ctx = await getLinkedinSupabaseSession();\n                if (ctx) captureLinkedinOAuthTokens(ctx.session);\n\n                let profileValue = \"\";\n                if (autoAuthenticated) {\n                  if (!ctx || !ctx.session) {\n                    result.innerHTML = `<div class=\"err\"><strong>Erro:</strong> Sessão LinkedIn expirada. Volta a iniciar sessão.</div>`;\n                    updateLinkedinAuthButtons(false);\n                    return;\n                  }\n                  let myUrl = myProfileInput ? myProfileInput.value.trim() : \"\";\n                  if (!myUrl) {\n                    await loadLinkedinProfileForSession(ctx.session);\n                    myUrl = myProfileInput ? myProfileInput.value.trim() : \"\";\n                  }\n                  if (!myUrl) await tryResolveLinkedinProfileUrl(ctx.sb);\n                  profileValue = canonicalizeLinkedinProfileUrl(myProfileInput ? myProfileInput.value.trim() : \"\") || \"\";\n                  if (!profileValue) {\n                    result.innerHTML = `<div class=\"err\"><strong>Erro:</strong> Cola o URL do teu perfil em «O meu perfil LinkedIn» e guarda na base de dados.</div>`;\n                    return;\n                  }\n                  if (myProfileInput) myProfileInput.value = profileValue;\n                } else {\n                  const rawOther = profileInput ? profileInput.value.trim() : \"\";\n                  profileValue = canonicalizeLinkedinProfileUrl(rawOther) || rawOther;\n                  if (!profileValue) {\n                    result.innerHTML = `<div class=\"err\"><strong>Erro:</strong> Cola o URL público em «Analisar outro perfil».</div>`;\n                    return;\n                  }\n                }\n\n                const endpoint = \"/agents/social-media/profile-analyze\";\n                const payload = {\n                  profile_input: profileValue,\n                  messages: [],\n                  language: \"pt-PT\",\n                  platform: \"linkedin\",\n                };\n                if (autoAuthenticated) {\n                  payload.link_as_own_profile = true;\n                  appendLinkedinSessionFields(payload, ctx.session, { includeStoredUrl: true });\n                }\n\n                const loadingHint = autoAuthenticated\n                  ? \"A recolher o teu perfil LinkedIn (sessão + Apify)…\"\n                  : \"LinkedIn (Apify + OpenAI) — pode demorar…\";\n                result.innerHTML = `\n                  <div class=\"loading\">\n                    <div class=\"spinner\"></div>\n                    <div>\n                      <div style=\"color: var(--text); font-weight:600\">A processar análise</div>\n                      <div style=\"font-size:0.85rem\">${escapeHtml(loadingHint)}</div>\n                    </div>\n                  </div>\n                `;\n\n                try {\n                  const response = await fetch(endpoint, {\n                    method: \"POST\",\n                    headers: { \"Content-Type\": \"application/json\" },\n                    credentials: \"same-origin\",\n                    body: JSON.stringify(payload),\n                  });\n                  const data = await response.json();\n                  if (!response.ok) {\n                    const detailText = data.detail || JSON.stringify(data);\n                    result.innerHTML = `<div class=\"err\"><strong>Erro:</strong> ${escapeHtml(detailText)}</div>`;\n                    return;\n                  }\n\n                  setLinkedinAnalysisSnapshot(data, autoAuthenticated);\n\n                  const profile = data.public_profile_data || {};\n                  const enrichment = profile.apify_enrichment || {};\n\n                  result.innerHTML = `\n                    ${renderHeader(data)}\n                    ${renderKpis(data)}\n                    ${renderTabs(autoAuthenticated)}\n\n                    <div id=\"panel-overview\" class=\"panel active\">\n                      <div class=\"section\">\n                        <h3>Principais Insights <span class=\"pill cool\">IA</span></h3>\n                        <ul class=\"insight-list\">${listSection(data.principais_insights)}</ul>\n                      </div>\n                      <div class=\"section\">\n                        <h3>Problemas Identificados <span class=\"pill\">atenção</span></h3>\n                        <ul class=\"insight-list problems\">${listSection(data.problemas_identificados)}</ul>\n                      </div>\n                      <div class=\"section\">\n                        <h3>Oportunidades <span class=\"pill cool\">crescimento</span></h3>\n                        <ul class=\"insight-list opps\">${listSection(data.oportunidades)}</ul>\n                      </div>\n                      <div class=\"section li-metrics-section\">\n                        <h3>Indicadores de desempenho <span class=\"pill cool\">LinkedIn</span></h3>\n                        <p class=\"section-desc\">Resumo quantitativo da página e das publicações analisadas. Campos sem dado público aparecem assinalados.</p>\n                        <div class=\"li-metrics-group\">\n                          <h4 class=\"li-metrics-group-title\">Métricas específicas (LinkedIn)</h4>\n                          ${renderLinkedinMetricCards(data.metricas_linkedin || data.metricas_instagram, data)}\n                        </div>\n                        <div class=\"li-metrics-group\">\n                          <h4 class=\"li-metrics-group-title\">Desempenho geral</h4>\n                          ${renderLinkedinMetricCards(data.metricas_universais, data)}\n                        </div>\n                      </div>\n                    </div>\n\n                    ${autoAuthenticated ? `\n                    <div id=\"panel-posts\" class=\"panel\">\n                      <div class=\"section\" data-section=\"posts-publicar\">\n                        <h3>Posts para publicar <span class=\"pill violet\">LinkedIn</span></h3>\n                        <p style=\"color:var(--muted);font-size:0.85rem;margin:0 0 10px\">Gera rascunhos do teu perfil com IA. Aprova, edita ou refaz cada publicação.</p>\n                        <div id=\"linkedinPostsContainer\" class=\"li-posts-wrap\"><div class=\"li-posts-loading\">Clica em <strong>Gerar posts</strong> para criar publicações com IA.</div></div>\n                        <button type=\"button\" class=\"btn-analyze\" style=\"margin-top:12px;max-width:260px\" id=\"btnGenerateLinkedinPosts\" data-action=\"generate-linkedin-posts\" onclick=\"generateLinkedinPostsFromSnapshot()\" disabled>Gerar posts</button>\n                      </div>\n                    </div>\n                    ` : \"\"}\n\n                    <div id=\"panel-content\" class=\"panel\">\n                      <div class=\"section\">\n                        <h3>Tipos de conteúdo LinkedIn</h3>\n                        ${renderFormatBars(enrichment.content_type_distribution || enrichment.format_distribution)}\n                      </div>\n                      <div class=\"section\">\n                        <h3>Top posts <span class=\"pill cool\">reações</span></h3>\n                        ${renderTopCards(enrichment.top_posts, \"top posts\")}\n                      </div>\n                      <div class=\"section\">\n                        <h3>Cadência de publicação</h3>\n                        ${renderCadence(enrichment.posting_cadence || {})}\n                      </div>\n                    </div>\n\n                    <div id=\"panel-evolution\" class=\"panel\">\n                      <div class=\"section\" data-section=\"acoes-prioritarias\">\n                        <h3>Ações Prioritárias <span class=\"pill\">agora</span></h3>\n                        <ul class=\"insight-list actions\">${listSection(data.acoes_prioritarias)}</ul>\n                      </div>\n                      <div class=\"section\" data-section=\"plano-crescimento\">\n                        <h3>Plano de Crescimento (curto prazo)</h3>\n                        <ul class=\"insight-list\">${listSection(data.plano_crescimento_curto_prazo)}</ul>\n                      </div>\n                      <div class=\"section\" data-section=\"ideias-conteudo\">\n                        <h3>Ideias por tipo de conteúdo <span class=\"pill violet\">LinkedIn</span></h3>\n                        <p style=\"color:var(--muted);font-size:0.85rem;margin:0 0 10px\">Formatos: post texto, artigo, documento/PDF, sondagem, vídeo nativo.</p>\n                        <ul class=\"insight-list violet\">${listSection(data.ideias_conteudo)}</ul>\n                      </div>\n                    </div>\n                                    `;\n                  attachTabHandlers();\n                  resetLinkedinPostsAfterAnalysis();\n                  enableGeneratePostsButton();\n                  const resolvedUrl = data.profile_url || profile.profile_url || profileValue;\n                  if (resolvedUrl && autoAuthenticated) saveLinkedinProfileUrl(resolvedUrl);\n                } catch (err) {\n                  const errorMessage = err instanceof Error ? err.message : String(err);\n                  result.innerHTML = `<div class=\"err\"><strong>Erro:</strong> ${escapeHtml(errorMessage)}</div>`;\n                }\n              }\n\n              async function runLinkedinAutoProfileAnalysis() {\n                const ctx = await getLinkedinSupabaseSession();\n                if (!ctx) {\n                  result.innerHTML = `<div class=\"err\"><strong>Erro:</strong> Inicia sessão com «Login LinkedIn (Supabase)» para usar a auto-análise.</div>`;\n                  updateLinkedinAuthButtons(false);\n                  return;\n                }\n                captureLinkedinOAuthTokens(ctx.session);\n                await runLinkedinProfileAnalysis({ autoAuthenticated: true });\n              }\n\n              if (profileInput) {\n                profileInput.addEventListener(\"keydown\", (e) => {\n                  if (e.key === \"Enter\") runLinkedinProfileAnalysis();\n                });\n              }\n              if (myProfileInput) {\n                myProfileInput.addEventListener(\"input\", updateAutoAnalyzeButton);\n              }\n\n              (async function setupLinkedinAuthListener() {\n                const sb = await getLinkedinSupabaseClient();\n                if (!sb) return;\n                sb.auth.onAuthStateChange((event, session) => {\n                  if (session) captureLinkedinOAuthTokens(session);\n                  if (event === \"SIGNED_IN\" && session) tryResolveLinkedinProfileUrl(sb);\n                  refreshLinkedinSupabaseSession();\n                });\n              })();\n\n              (async function bootstrapLinkedinPage() {\n                await initSupabaseAuthFromUrl();\n                applyStoredLinkedinProfileUrl();\n                await refreshLinkedinSupabaseSession();\n              })();\n            </script>\n          </body>\n        </html>\n"
